11	
12		@Test
13		void coreRejectsSameLastNameAndAddress() throws Exception {
14			ObjectNode a = ownerNode();
15			createOwnerOk(a);
16			ObjectNode b = ownerNode();
17			b.put("lastName", a.get("lastName").asText()); b.put("address", a.get("address").asText());
18			createOwner(b).andExpect(status().isConflict());
19		}
